// Keep only postings that are genuinely new: drop the run SUMMARY and any
// ERROR rows, drop postings whose Dice job ID is already in the Log sheet,
// and drop duplicates inside this batch. When nothing is new, emit ONE
// marker item so the loop still advances to the next search. New postings
// beyond the per-search alert cap are left unlogged on purpose: they stay
// inside the posted window and surface on the next run instead of flooding
// the channel today.
const settings = $('Set your watch settings').first().json;
const cap = Number(settings.max_alerts_per_search) || 10;
const logged = new Set(
  $('Read alert log').all()
    .map(i => String(i.json.diceJobId ?? ''))
    .filter(Boolean)
);
const seenThisRun = new Set();
const fresh = [];
for (const { json: j } of $input.all()) {
  if (!j.diceJobId) continue;
  if (j.recordType === 'SUMMARY' || j.recordType === 'ERROR') continue;
  const id = String(j.diceJobId);
  if (logged.has(id) || seenThisRun.has(id)) continue;
  seenThisRun.add(id);
  fresh.push({ json: {
    diceJobId: id,
    jobTitle: j.jobTitle ?? '',
    company: j.company ?? '',
    location: j.location ?? '',
    employmentType: j.employmentType ?? '',
    workplaceTypes: (j.workplaceTypes ?? []).join(', '),
    salary: j.salary ?? '',
    postedDate: j.postedDate ?? '',
    summary: j.summary ?? '',
    jobUrl: j.jobUrl ?? '',
    isNew: 1,
  }});
}
const capped = fresh.slice(0, cap);
if (!capped.length) {
  return [{ json: { noneFound: true, isNew: 0 } }];
}
return capped;

