// Assemble the Slack alert text and the Log-sheet row for one new posting:
// the posting fields come from the filter node, the AI summary is this
// item's input (the LLM chain's text output).
const j = $('Keep only new jobs').item.json;
const summary = $json.text ?? '';
const payLine = j.salary ? `\nPay (as listed): ${j.salary}` : '';
const alertText = [
  '\uD83C\uDD95 New Dice posting',
  `*${j.jobTitle}* at ${j.company}`,
  `${j.location || 'Location not listed'} \u00B7 ${j.employmentType} \u00B7 ${j.workplaceTypes} \u00B7 Posted ${String(j.postedDate).slice(0, 10)}${payLine}`,
  summary,
  `Posting: ${j.jobUrl}`,
].join('\n');
return { json: {
  diceJobId: j.diceJobId,
  jobTitle: j.jobTitle,
  company: j.company,
  location: j.location,
  aiSummary: summary,
  dateLogged: new Date().toISOString().slice(0, 10),
  alertText,
} };
